'use strict';
const examples={link:{input:'https://somewhere.nice/a-place-worth-keeping',mark:'↗',type:'LINK + YOUR NOTE',title:'That little place for the weekend.',description:'Keep the original link and a little context. No folder decision required.'},note:{input:'Maybe the best ideas just need a place to stay.',mark:'Aa',type:'A THOUGHT, KEPT',title:'An idea before it disappears.',description:'A sentence is enough. Find it later with a word you remember.'},image:{input:'A screenshot from your camera roll',mark:'▧',type:'IMAGE + SEARCHABLE TEXT · PLANNED',title:'The details you meant to remember.',description:'The goal: keep the image and search its text. OCR is part of the first-build brief.'}};
document.querySelectorAll('[data-example]').forEach(b=>b.addEventListener('click',()=>{const e=examples[b.dataset.example];for(const key of ['input','mark','type','title','description'])document.getElementById('example-'+key).textContent=e[key];document.querySelectorAll('[data-example]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)))}));
